/**
 * Single source of truth for building the OpenAPI spec from JSDoc comments.
 * Used by:
 *   - scripts/update-spec.js  (regenerate + overwrite openapi.json)
 *   - scripts/spec-check.js   (CI guard: regenerate + diff against committed file)
 *   - test/spec-check.test.js (proves the guard trips on drift)
 */

const path = require('path');
const swaggerJsdoc = require('swagger-jsdoc');

const ROOT = path.join(__dirname, '..');

/** Default source files scanned for @openapi JSDoc blocks. */
const DEFAULT_APIS = [path.join(ROOT, 'src', 'routes', '*.js')];

const DEFINITION = {
  openapi: '3.0.0',
  info: {
    title: 'Pets API',
    version: '1.0.0',
    description: 'Documented with swagger-jsdoc',
  },
  servers: [{ url: '/' }],
  tags: [{ name: 'Pets' }],
};

/**
 * Build the OpenAPI object.
 * @param {string[]|undefined} apis - glob(s) to scan; defaults to src/routes/*.js
 */
function buildSpec(apis) {
  const spec = swaggerJsdoc({
    definition: DEFINITION,
    apis: apis || DEFAULT_APIS,
  });
  return spec;
}

/** Canonical serialization used both when committing and when checking. */
function serializeSpec(spec) {
  return JSON.stringify(spec, null, 2) + '\n';
}

module.exports = { buildSpec, serializeSpec, DEFAULT_APIS, ROOT };
