/** Minimal dependency-free LCS line diff, rendered like `diff -u`. */

function diffLines(aLines, bLines) {
  const n = aLines.length;
  const m = bLines.length;
  // LCS table (fine for spec-sized files)
  const dp = Array.from({ length: n + 1 }, () => new Uint32Array(m + 1));
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      dp[i][j] =
        aLines[i] === bLines[j] ? dp[i + 1][j + 1] + 1 : Math.max(dp[i + 1][j], dp[i][j + 1]);
    }
  }
  const ops = []; // { type: ' ' | '-' | '+', line }
  let i = 0;
  let j = 0;
  while (i < n && j < m) {
    if (aLines[i] === bLines[j]) {
      ops.push({ type: ' ', line: aLines[i] });
      i++;
      j++;
    } else if (dp[i + 1][j] >= dp[i][j + 1]) {
      ops.push({ type: '-', line: aLines[i++] });
    } else {
      ops.push({ type: '+', line: bLines[j++] });
    }
  }
  while (i < n) ops.push({ type: '-', line: aLines[i++] });
  while (j < m) ops.push({ type: '+', line: bLines[j++] });
  return ops;
}

/**
 * Render a unified-style diff with 2 context lines around hunks.
 * @returns {string} empty string when there are no differences
 */
function unifiedDiff(aText, bText, aName = 'committed', bName = 'regenerated') {
  const a = aText.split('\n');
  const b = bText.split('\n');
  const ops = diffLines(a, b);
  if (!ops.some((op) => op.type !== ' ')) return '';

  const CONTEXT = 2;
  const keep = new Array(ops.length).fill(false);
  ops.forEach((op, idx) => {
    if (op.type === ' ') return;
    for (let k = Math.max(0, idx - CONTEXT); k <= Math.min(ops.length - 1, idx + CONTEXT); k++) {
      keep[k] = true;
    }
  });

  const out = [`--- ${aName}`, `+++ ${bName}`];
  let hunkStart = -1;
  let aLine = 0;
  let bLine = 0;

  const flushHunk = (end) => {
    const slice = [];
    for (let k = hunkStart; k <= end; k++) slice.push({ ...ops[k], idx: k });
    const aCount = slice.filter((l) => l.type !== '+').length;
    const bCount = slice.filter((l) => l.type !== '-').length;
    out.push(`@@ -${slice[0].aNo},${aCount} +${slice[0].bNo},${bCount} @@`);
    for (const l of slice) {
      out.push(`${l.type} ${l.line}`);
    }
    hunkStart = -1;
  };

  // annotate line numbers
  let aNo = 1;
  let bNo = 1;
  ops.forEach((op) => {
    op.aNo = aNo;
    op.bNo = bNo;
    if (op.type !== '+') aNo++;
    if (op.type !== '-') bNo++;
  });

  for (let k = 0; k < ops.length; k++) {
    if (keep[k]) {
      if (hunkStart === -1) hunkStart = k;
      if (k === ops.length || !keep[k + 1]) flushHunk(k);
    } else if (hunkStart !== -1 && !keep[k]) {
      flushHunk(k - 1);
    }
  }
  if (hunkStart !== -1) flushHunk(ops.length - 1);

  return out.join('\n') + '\n';
}

module.exports = { unifiedDiff };
"})
