'use strict';

/**
 * OpenAPI drift guard.
 *
 * Regenerates the spec from JSDoc comments and compares it byte-for-byte
 * against the committed openapi.json. Exits 1 with a readable diff on drift.
 *
 * Environment overrides (used by tests):
 *   SPEC_APIS  comma-separated glob(s) of source files to scan
 *   SPEC_PATH  path of the committed spec file (default: <repo>/openapi.json)
 *
 * Usage:
 *   npm run spec:check    # verify (CI guard, exit 1 on drift)
 *   npm run spec:update   # regenerate openapi.json after intentional changes
 */

const fs = require('fs');
const path = require('path');
const { buildSpec, serializeSpec, DEFAULT_APIS } = require('./generate-spec');
const { unifiedDiff } = require('./diff');

function main() {
  const apis = process.env.SPEC_APIS
    ? process.env.SPEC_APIS.split(',').map((p) => p.trim()).filter(Boolean)
    : DEFAULT_APIS;
  const specPath = process.env.SPEC_PATH || path.join(__dirname, '..', 'openapi.json');

  let committed;
  try {
    committed = fs.readFileSync(specPath, 'utf8');
  } catch {
    console.error(`✗ ${specPath} not found.`);
    console.error('  Run `npm run spec:update` to generate it, then commit the result.');
    return 1;
  }

  const regenerated = serializeSpec(buildSpec(apis));

  if (committed === regenerated) {
    console.log(`✓ ${path.relative(process.cwd(), specPath) || specPath} is up to date`);
    return 0;
  }

  console.error(
    [
      '✗ openapi.json has drifted from the documented routes!',
      '',
      '  Diff (< committed openapi.json  > regenerated from JSDoc):',
      '',
      unifiedDiff(committed, regenerated),
      '',
      '  If this change is intentional:',
      '    npm run spec:update && git add openapi.json',
      '  Otherwise, update the @openapi JSDoc blocks or remove the route.',
    ].join('\n')
  );
  return 1;
}

process.exitCode = main();
"})
