const test = require('node:test');
const assert = require('node:assert/strict');
const { spawnSync } = require('node:child_process');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');

const ROOT = path.join(__dirname, '..');
const SPEC_CHECK = path.join(ROOT, 'scripts', 'spec-check.js');
const COMMITTED_SPEC = path.join(ROOT, 'openapi.json');

function runChecker(env) {
  return spawnSync(process.execPath, [SPEC_CHECK], {
    cwd: ROOT,
    env: { ...process.env, ...env },
    encoding: 'utf8',
  });
}

function makeTmpDir() {
  return fs.mkdtempSync(path.join(os.tmpdir(), 'spec-drift-'));
}

test('committed openapi.json matches the documented routes (real app)', () => {
  const result = runChecker();
  assert.equal(
    result.status,
    0,
    `spec:check should pass on the real app.\nstdout: ${result.stdout}\nstderr: ${result.stderr}`
  );
  assert.match(result.stdout, /up to date/);
});

